const message = $input.first().json;
const text = message.message?.text || message.text || '';
const chatId = message.message?.chat?.id || message.chat?.id;
const messageId = message.message?.message_id || message.update_id;
const timestamp = new Date().toISOString();

// Only the owner may use the assistant. Deny by default if the env var is missing.
const allowedChat = String($env.TELEGRAM_CHAT_ID || '');
if (!allowedChat || String(chatId) !== allowedChat) return [];

let command = null;
let args = text;
if (text.startsWith('/')) {
  const match = text.match(/^\/(\w+)\s*(.*)$/s);
  if (match) {
    command = match[1].toLowerCase();
    args = match[2].trim();
  }
}

return [{
  json: {
    source: 'telegram',
    external_id: String(messageId),
    chat_id: String(chatId),
    text,
    command,
    args,
    timestamp
  }
}];

