const fs = require('fs');
const initSqlJs = require('/home/node/.n8n/nodes/node_modules/sql.js');
const DB_PATH = '/home/node/.n8n/assistant.db';
let text = '';
try {
  const origin = $('ParseCommand').item.json;
  text = origin.text || '';
} catch(e) {
  const input = $input.first().json;
  text = input.original_text || '';
}
const SQL = await initSqlJs();
const db = new SQL.Database(fs.readFileSync(DB_PATH));
const commonWords = new Set(['the','a','an','is','was','were','have','has','had','do','does','did','will','would','could','should','can','to','of','in','for','on','with','at','by','from','this','that','i','you','he','she','it','we','they','my','your','his','her','me','him','us','what','which','who','when','where','how','why','and','but','or','not','no','yes','ok','thanks','hello','hi','hey','yeah','nah','lol','task','tasks','logged','total','done','status','help','checkin','plan']);
const words = text.split(/\s+/);
const names = words.filter(w => { const c = w.replace(/[^a-zA-Z]/g,''); return c.length > 2 && c[0] === c[0].toUpperCase() && !commonWords.has(c.toLowerCase()); }).slice(0,3);
for (const name of [...new Set(names)]) {
  try {
    const ex = db.exec('SELECT id FROM contacts WHERE name = ' + "'" + name.replace(/'/g,"''") + "'");
    if (!ex[0]?.values.length) db.run('INSERT INTO contacts (name, last_interaction) VALUES (?, datetime(' + "'now'" + '))', [name]);
    else db.run('UPDATE contacts SET last_interaction = datetime(' + "'now'" + ') WHERE id = ?', [ex[0].values[0][0]]);
  } catch(e) {}
}
fs.writeFileSync(DB_PATH + '.tmp', Buffer.from(db.export())); fs.renameSync(DB_PATH + '.tmp', DB_PATH);
db.close();
return [{ json: $input.first().json }];
